def require_fixed(expected):
    got=pin(expected['path']);assert got==expected
    return got

def pairs(items):
    result={}
    for key,value in items:
        assert key not in result,'duplicate saved JSON field'
        result[key]=value
    return result

def finite(value):raise ValueError('nonfinite saved JSON: '+value)

def read_json(p):
    p=Path(p);before=pin(p)
    with p.open('rt',encoding='utf8') as f:v=json.load(f,object_pairs_hook=pairs,parse_constant=finite)
    assert pin(p)==before and type(v) is dict
    return v

def directory_identity(path):
    s=Path(path).lstat();assert stat.S_ISDIR(s.st_mode) and not Path(path).is_symlink()
    return identity(s)

def full_namespace(root):
    directories=[];files=[]
    for parent,dirs,names in os.walk(root,followlinks=False):
        dirs.sort();names.sort();directory=Path(parent)
        directories.append(dict(path=str(directory),identity=directory_identity(directory)))
        for name in dirs:assert not (directory/name).is_symlink()
        for name in names:files.append(pin(directory/name))
    return dict(root=str(root),directories=directories,files=files,symlinks=[])

def original_protocol_archive():
    fresh={name:full_namespace(ns['root']) for name,ns in FROZEN_COMPLETE_NAMESPACES.items()}
    assert fresh==FROZEN_COMPLETE_NAMESPACES
    actual=sum(p['size_bytes'] for ns in fresh.values() for p in ns['files'])
    assert actual<64*2**20
    return dict(complete_H_O_Source_receipts_regular_bytes=actual,original_cap_bytes=64*2**20,complete_namespaces=fresh)

def gzip_object(desc):
    before=pin(desc['path'])
    assert {k:before[k] for k in ('path','sha256','identity')}=={k:desc[k] for k in ('path','sha256','identity')} and before['size_bytes']==desc['size_bytes']
    assert desc['complete_JSON_wire_gzip_decompression_EOF_SHA_verified'] is True and desc['no_fields_or_records_filtered'] is True
    count=0;h=hashlib.sha256()
    with gzip.open(desc['path'],'rb') as f:
        for block in iter(lambda:f.read(524288),b''):count+=len(block);h.update(block)
    assert type(desc['uncompressed_JSON_bytes']) is int and count==desc['uncompressed_JSON_bytes'] and h.hexdigest()==desc['uncompressed_JSON_sha256']
    with gzip.open(desc['path'],'rt',encoding='ascii') as f:value=json.load(f,object_pairs_hook=pairs,parse_constant=finite)
    assert type(value) is dict and pin(desc['path'])==before
    checkpoint()
    return value

def compare_full_gzip_bytes(left,right):
    count=0;h=hashlib.sha256()
    with gzip.open(left['path'],'rb') as a,gzip.open(right['path'],'rb') as b:
        while True:
            av=a.read(524288);bv=b.read(524288);assert av==bv
            if not av:break
            count+=len(av);h.update(av)
    assert count==left['uncompressed_JSON_bytes']==right['uncompressed_JSON_bytes'] and h.hexdigest()==left['uncompressed_JSON_sha256']==right['uncompressed_JSON_sha256']
    return dict(full_uncompressed_byte_comparison=True,full_both_EOF=True,bytes=count,sha256=h.hexdigest(),fields_or_rows_selected=False)

def save_json(p,value):
    with p.open('x',encoding='utf8') as f:json.dump(value,f,indent=2,allow_nan=False);f.write('\n');f.flush();os.fsync(f.fileno())
    return pin(p)

